import{_ as t,o,c as d,a5 as a}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"Plan — FR 3.2.2: Sign In with Email","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/01-authentication/3-2-2-sign-in-with-email/plan.md","filePath":"feature/srs/01-authentication/3-2-2-sign-in-with-email/plan.md"}'),c={name:"feature/srs/01-authentication/3-2-2-sign-in-with-email/plan.md"};function n(i,e,r,s,l,u){return o(),d("div",null,[...e[0]||(e[0]=[a('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="plan-—-fr-3-2-2-sign-in-with-email" tabindex="-1">Plan — FR 3.2.2: Sign In with Email <a class="header-anchor" href="#plan-—-fr-3-2-2-sign-in-with-email" aria-label="Permalink to &quot;Plan — FR 3.2.2: Sign In with Email&quot;">​</a></h1><p>&gt; Implements <a href="./spec.html">spec.md</a> — Direct credential sign-in (<code>POST /api/v1/auth/login</code>), status &amp; verification gates (<code>BR-02</code>, <code>BR-05</code>), conditional 2FA TOTP challenge handoff (<code>FR 3.2.7</code>), and JWT session issuance.</p><h2 id="_1-technical-component-map" tabindex="-1">1. Technical Component Map <a class="header-anchor" href="#_1-technical-component-map" aria-label="Permalink to &quot;1. Technical Component Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Layer</th><th style="text-align:left;">Repository / Package</th><th style="text-align:left;">Concrete Classes &amp; Files</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>API Gateway</strong></td><td style="text-align:left;"><code>brandhub-api-gateway</code></td><td style="text-align:left;"><code>GatewayConfig.java</code> (<code>/api/v1/auth/login</code>, <code>/api/v1/auth/refresh</code>), <code>RateLimitGatewayFilterFactory.java</code></td></tr><tr><td style="text-align:left;"><strong>Controller</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>controller/auth/AuthController.java</code> (<code>login</code>, <code>refresh</code>, <code>me</code>, <code>getSessions</code>, <code>revokeOtherSessions</code>)</td></tr><tr><td style="text-align:left;"><strong>Service</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>service/impl/auth/AuthServiceImpl.java</code> (<code>login</code>, <code>checkStatus</code>, <code>completeLogin</code>, <code>refresh</code>), <code>util/JwtUtil.java</code></td></tr><tr><td style="text-align:left;"><strong>DTOs &amp; Errors</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>LoginRequest</code>, <code>LoginResponse</code> (<code>accessToken</code>, <code>expiresIn</code>, <code>requireTwoFactor</code>, <code>twoFactorToken</code>), <code>ErrorCode</code> (<code>INVALID_CREDENTIALS</code>, <code>EMAIL_NOT_VERIFIED</code>, <code>ACCOUNT_DEACTIVATED</code>, <code>ACCOUNT_SUSPENDED</code>)</td></tr><tr><td style="text-align:left;"><strong>Persistence</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>UserRepository</code>, <code>UserRefreshTokenRepository</code>, <code>AuditLogRepository</code></td></tr><tr><td style="text-align:left;"><strong>Web Frontend</strong></td><td style="text-align:left;"><code>brandhub-web</code></td><td style="text-align:left;"><code>src/pages/auth/LoginPage.tsx</code>, <code>src/components/auth/DevQuickLogin.tsx</code>, <code>src/services/authService.ts</code>, <code>src/stores/authStore.ts</code></td></tr><tr><td style="text-align:left;"><strong>Mobile App</strong></td><td style="text-align:left;"><code>brandhub-mobile-app</code></td><td style="text-align:left;"><code>app/(auth)/login.tsx</code>, <code>src/services/authService.ts</code>, <code>src/store/authStore.ts</code></td></tr></tbody></table><h2 id="_2-database-session-schema" tabindex="-1">2. Database &amp; Session Schema <a class="header-anchor" href="#_2-database-session-schema" aria-label="Permalink to &quot;2. Database &amp; Session Schema&quot;">​</a></h2><ul><li><strong>PostgreSQL <code>users</code>:</strong> Reads normalized <code>email</code> / <code>phone</code>, <code>password_hash</code>, <code>status</code> (<code>ACTIVE</code> / <code>DEACTIVATED</code> / <code>SUSPENDED</code>), <code>email_verified_at</code>, <code>two_factor_enabled</code>, <code>last_login_at</code>, <code>last_password_change</code>.</li><li><strong>PostgreSQL <code>user_refresh_tokens</code>:</strong> Persists hashed/tracked 30-day refresh session metadata (<code>user_id</code>, <code>token_hash</code> / <code>jti</code>, <code>device_info</code>, <code>ip_address</code>, <code>expires_at</code>, <code>revoked_at</code>) enabling active device listing (<code>/api/v1/auth/sessions</code>) and rotation.</li><li><strong>PostgreSQL <code>audit_logs</code>:</strong> Records <code>AuditAction.LOGIN</code> with <code>ip_address</code> and <code>user_agent</code>.</li></ul><h2 id="_3-end-to-end-execution-flow" tabindex="-1">3. End-to-End Execution Flow <a class="header-anchor" href="#_3-end-to-end-execution-flow" aria-label="Permalink to &quot;3. End-to-End Execution Flow&quot;">​</a></h2><ol><li><strong>Credential Normalization &amp; Lookup:</strong> <code>AuthServiceImpl.login()</code> normalizes <code>identifier</code> (lowercase + trim); if no <code>User</code> matches or <code>passwordHash == null</code> (Google OAuth-only account) or BCrypt verification fails -&gt; returns uniform <code>401 INVALID_CREDENTIALS</code> (preventing account enumeration).</li><li><strong>Account Lifecycle &amp; Verification Gate (<code>BR-05</code>):</strong><ul><li><code>checkStatus(user)</code> rejects <code>UserStatus.DEACTIVATED</code> -&gt; <code>403 ACCOUNT_DEACTIVATED</code> and <code>UserStatus.SUSPENDED</code> -&gt; <code>403 ACCOUNT_SUSPENDED</code>.</li><li>Rejects unverified email (<code>emailVerifiedAt == null</code>) -&gt; <code>403 EMAIL_NOT_VERIFIED</code> so UI can route user to <code>/verify-otp</code>.</li></ul></li><li><strong>2FA Challenge Branch vs Full Session Issuance:</strong><ul><li>If <code>user.isTwoFactorEnabled()</code> is <code>true</code>: <code>JwtUtil.generateTwoFactorToken(userId)</code> issues a 5-minute <code>type=2fa</code> challenge token and returns <code>LoginResponse.twoFactorChallenge(twoFactorToken)</code> (<code>requireTwoFactor = true</code>, no <code>accessToken</code> or refresh cookie). Client navigates to <code>/2fa-verify</code>.</li><li>If <code>twoFactorEnabled</code> is <code>false</code>: <code>completeLogin()</code> mints a 15-minute <code>accessToken</code>, persists and sets the 30-day <code>HttpOnly</code> <code>refreshToken</code> cookie, updates <code>lastLoginAt</code>, writes <code>AuditLog(LOGIN)</code>, and returns <code>200 LoginResponse</code>.</li></ul></li></ol><h2 id="_4-dev-quick-login-alignment-2026-10-04" tabindex="-1">4. Dev Quick Login Alignment (2026-10-04) <a class="header-anchor" href="#_4-dev-quick-login-alignment-2026-10-04" aria-label="Permalink to &quot;4. Dev Quick Login Alignment (2026-10-04)&quot;">​</a></h2><ul><li><code>src/main/resources/seed/dev-quick-login.sql</code> idempotently provisions demo accounts in PostgreSQL with fixed UUIDs and <code>pgcrypto</code> BCrypt hashes without touching existing accounts.</li><li><code>brandhub-web/src/components/auth/DevQuickLogin.tsx</code> resolves post-login role routing dynamically via <code>workspaceService.list()</code> (<code>myRole</code>) for <code>Manager</code> and <code>Creator</code> accounts, preserving <code>Admin</code>, <code>Owner</code>, and <code>Client</code> landing routes and routing <code>requireTwoFactor</code> challenges to <code>/2fa-verify</code>.</li></ul><h2 id="_5-security-anti-enumeration-guards" tabindex="-1">5. Security &amp; Anti-Enumeration Guards <a class="header-anchor" href="#_5-security-anti-enumeration-guards" aria-label="Permalink to &quot;5. Security &amp; Anti-Enumeration Guards&quot;">​</a></h2><ul><li><strong>Uniform Credential Error:</strong> Wrong email, OAuth-only account without password, and wrong password all return identical <code>401 INVALID_CREDENTIALS</code> timing/status semantics.</li><li><strong>Refresh Token Freshness (<code>BR-08</code>):</strong> <code>AuthServiceImpl.refresh()</code> rejects any refresh token issued prior to <code>user.getLastPasswordChange()</code> or blacklisted in Redis.</li></ul><h2 id="endpoint-authorization-error-mapping-matrix" tabindex="-1">Endpoint, Authorization &amp; Error Mapping Matrix <a class="header-anchor" href="#endpoint-authorization-error-mapping-matrix" aria-label="Permalink to &quot;Endpoint, Authorization &amp; Error Mapping Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Aspect</th><th style="text-align:left;">Specification</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR / Feature</strong></td><td style="text-align:left;"><code>FR 3.2.2</code> — Sign In with Email</td></tr><tr><td style="text-align:left;"><strong>HTTP / WS Endpoints</strong></td><td style="text-align:left;"><code>POST /api/v1/auth/login · POST /api/v1/auth/refresh</code></td></tr><tr><td style="text-align:left;"><strong>Authorized Canonical Roles</strong></td><td style="text-align:left;"><code>Guest, Owner, Manager, Creator, Client, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Controller -&gt; Service</strong></td><td style="text-align:left;"><code>AuthController</code> -&gt; <code>AuthServiceImpl, JwtUtil</code></td></tr><tr><td style="text-align:left;"><strong>Persistence / Cache Targets</strong></td><td style="text-align:left;">PostgreSQL <code>users</code>, <code>user_refresh_tokens</code>, <code>audit_logs</code></td></tr><tr><td style="text-align:left;"><strong>Business Rule Invariants</strong></td><td style="text-align:left;"><code>BR-02, BR-05</code></td></tr><tr><td style="text-align:left;"><strong>Error Code Contract</strong></td><td style="text-align:left;"><code>401 INVALID_CREDENTIALS</code>, <code>403 EMAIL_NOT_VERIFIED</code> / <code>ACCOUNT_DEACTIVATED</code> / <code>ACCOUNT_SUSPENDED</code></td></tr></tbody></table><h2 id="frontend-cache-i18n-theme-architecture" tabindex="-1">Frontend Cache, i18n &amp; Theme Architecture <a class="header-anchor" href="#frontend-cache-i18n-theme-architecture" aria-label="Permalink to &quot;Frontend Cache, i18n &amp; Theme Architecture&quot;">​</a></h2><ul><li><strong>Web State &amp; Query Management (<code>brandhub-web</code>):</strong><ul><li>Components &amp; Hooks: <code>src/pages/auth/LoginPage.tsx</code>, <code>src/components/auth/DevQuickLogin.tsx</code>, <code>src/services/authService.ts</code>, <code>src/stores/authStore.ts</code>.</li><li>Query Keys &amp; Cache Invalidation: Scoped by authenticated <code>userId</code>, <code>agencyId</code>, or <code>workspaceId</code> so switching tenants or logging out never leaks cached records across boundaries.</li><li>Conflict &amp; Error Recovery: Preserves in-progress user form state on <code>400</code>/<code>409</code> responses, disables duplicate in-flight submissions, and never falls back to hardcoded mock data.</li></ul></li><li><strong>Mobile Parity (<code>brandhub-mobile-app</code>):</strong><ul><li>Screens &amp; Services: <code>app/(auth)/login.tsx</code>, <code>src/services/authService.ts</code>, <code>src/store/authStore.ts</code>.</li><li>Uses shared REST/WS contract, <code>expo-secure-store</code> Bearer token injection, and mobile <code>workspaceStore</code> / <code>authStore</code> synchronization.</li></ul></li><li><strong>Localization &amp; Theme Standards:</strong><ul><li>Key-parallel Vietnamese (<code>vi</code>) and English (<code>en</code>) locale entries under <code>auth.login.*</code> with zero hardcoded strings.</li><li>Semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useTheme()</code> semantic tokens on Mobile verified across Light and Dark modes.</li></ul></li><li><strong>Observability &amp; Audit Correlation:</strong><ul><li>Propagates <code>X-Request-Id</code> from <code>brandhub-api-gateway</code> into <code>ApiResponse.requestId</code> and structured backend logs / <code>audit_logs</code> where security-sensitive mutations occur.</li></ul></li><li><strong>BA &amp; Module Traceability:</strong> <a href="./../../../../ba/02-authentication-profile.html">BA Domain Spec</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a>.</li></ul>',17)])])}const p=t(c,[["render",n]]);export{h as __pageData,p as default};
